function normalize(raw) {
  const source = raw && typeof raw === "object" ? raw : EMPTY;
  const users = (Array.isArray(source.users) && source.users.length ? source.users : DEFAULT_USERS).map((item, index) => ({ id: text(item.id || `consultant-${index + 1}`, 40), name: text(item.name, 100), role: item.role === "ADMIN" ? "ADMIN" : "OPERACIONAL" })).filter((item) => item.id && item.name);
  return {
    users: users.length ? users : DEFAULT_USERS,
    clients: (source.clients || []).map((item, index) => ({ id: Number(item.id) || index + 1, name: text(item.name, 180), city: text(item.city, 80), state: text(item.state, 2).toUpperCase(), phone: text(item.phone, 40), whatsapp: text(item.whatsapp, 40), mainActivity: text(item.mainActivity, 100), notes: text(item.notes, 2000) })).filter((item) => item.name),
    farms: (source.farms || []).map((item, index) => ({ id: Number(item.id) || index + 1, name: text(item.name, 180), clientId: Number(item.clientId) || null, city: text(item.city, 80), state: text(item.state, 2).toUpperCase(), mainActivity: text(item.mainActivity, 100), notes: text(item.notes, 2000) })).filter((item) => item.name),
    plans: (source.plans || []).map((item, index) => ({ id: Number(item.id) || index + 1, userId: text(item.userId, 40), clientId: Number(item.clientId) || null, farmId: Number(item.farmId) || null, clientName: text(item.clientName, 180), farmName: text(item.farmName, 180), scheduledDate: text(item.scheduledDate, 10), status: ["PLANNED", "COMPLETED", "NOT_DONE"].includes(item.status) ? item.status : "PLANNED", notDoneReason: text(item.notDoneReason, 100), notDoneNote: text(item.notDoneNote, 500) })),
    visits: (source.visits || []).map((item, index) => ({ id: Number(item.id) || index + 1, userId: text(item.userId, 40), planId: Number(item.planId) || null, clientId: Number(item.clientId) || null, farmId: Number(item.farmId) || null, clientName: text(item.clientName, 180), farmName: text(item.farmName, 180), visitedAt: item.visitedAt || new Date().toISOString(), developed: text(item.developed || item.result, 2000), types: Array.isArray(item.types) ? item.types.filter((type) => VISIT_TYPES.some(([id]) => id === type)) : [], businessType: text(item.businessType, 100), saleValue: Number(item.saleValue) || 0, nextAction: text(item.nextAction, 500) })),
  };
}
function loadData() { try { const saved = localStorage.getItem(STORAGE_KEY); if (saved) return normalize(JSON.parse(saved)); return normalize(JSON.parse(localStorage.getItem(PREVIOUS_KEY) || "null")); } catch { return EMPTY; } }
function Field({ label, value, onChange, required, type = "text", placeholder, min, step }) { return <div className="source-field"><label>{label}</label><input type={type} value={value} onChange={(event) => onChange(event.target.value)} required={required} placeholder={placeholder} min={min} step={step} /></div>; }
function StateCityFields({ state, city, onChange }) { const cities = CITIES_BY_STATE[state] || []; const citiesListId = `cities-${state || "state"}`; return <div className="source-grid"><div className="source-field"><label>UF</label><select value={state} onChange={(event) => onChange({ state: event.target.value, city: "" })}>{BR_STATES.map((item) => <option key={item.sigla} value={item.sigla}>{item.sigla} — {item.nome}</option>)}</select></div><div className="source-field"><label>Cidade</label><input value={city} list={citiesListId} onChange={(event) => onChange({ state, city: event.target.value })} disabled={!state} placeholder={state ? "Digite ou selecione uma cidade" : "Selecione primeiro a UF"} /><datalist id={citiesListId}>{cities.map((item) => <option key={item} value={item} />)}</datalist></div></div>; }
function Empty({ children }) { return <div className="empty"><p>{children}</p></div>; }
function Panel({ title, children }) { const displayTitle = typeof title === "string" ? title.replace(/(—\s)(\p{Ll})/u, (_, prefix, letter) => `${prefix}${letter.toLocaleUpperCase("pt-BR")}`) : title; return <section className="panel"><h3>{displayTitle}</h3>{children}</section>; }
function Metric({ label, value, detail }) { return <article className="metric"><span>{label}</span><strong>{value}</strong><em>{detail}</em></article>; }
function toBrazilianDate(value) { const [year, month, day] = String(value || "").slice(0, 10).split("-"); return year && month && day ? `${day}/${month}/${year}` : ""; }
function toBrazilianDateTime(value) { const [date, time = ""] = String(value || "").split("T"); return `${toBrazilianDate(date)}${time ? ` ${time.slice(0, 5)}` : ""}`.trim(); }
function validDate(day, month, year) { const date = new Date(Number(year), Number(month) - 1, Number(day)); return date.getFullYear() === Number(year) && date.getMonth() === Number(month) - 1 && date.getDate() === Number(day); }
function CalendarPicker({ value, onChange, withTime = false }) {
  const initial = String(value || new Date().toISOString()).slice(0, 10); const [open, setOpen] = useState(false); const [cursor, setCursor] = useState(new Date(`${initial}T12:00:00`)); const pickerRef = useRef(null);
  useEffect(() => setCursor(new Date(`${String(value || initial).slice(0, 10)}T12:00:00`)), [value]);
  useEffect(() => { if (!open) return undefined; const close = (event) => { if (!pickerRef.current?.contains(event.target)) setOpen(false); }; document.addEventListener("pointerdown", close); return () => document.removeEventListener("pointerdown", close); }, [open]);
  const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1); const offset = (first.getDay() + 6) % 7; const days = new Date(cursor.getFullYear(), cursor.getMonth() + 1, 0).getDate(); const cells = Array.from({ length: offset + days }, (_, index) => index < offset ? null : index - offset + 1); const time = String(value || "").slice(11, 16) || "00:00";
  const setDate = (day) => { const iso = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`; onChange(withTime ? `${iso}T${time}` : iso); setOpen(false); };
  const setTime = (part, next) => { const [hour, minute] = time.split(":"); onChange(`${String(value).slice(0, 10)}T${part === "hour" ? next : hour}:${part === "minute" ? next : minute}`); };
  return <div className="source-picker" ref={pickerRef}><button type="button" className="source-picker-trigger" onClick={() => setOpen(!open)} aria-expanded={open}>{toBrazilianDate(value)}{withTime ? ` ${time}` : ""}<span>▾</span></button>{withTime && <div className="source-time"><select value={time.slice(0, 2)} onChange={(event) => setTime("hour", event.target.value)}>{Array.from({ length: 24 }, (_, item) => String(item).padStart(2, "0")).map((item) => <option key={item}>{item}</option>)}</select><b>:</b><select value={time.slice(3, 5)} onChange={(event) => setTime("minute", event.target.value)}>{Array.from({ length: 60 }, (_, item) => String(item).padStart(2, "0")).map((item) => <option key={item}>{item}</option>)}</select></div>}{open && <div className="source-calendar"><div className="source-calendar-head"><button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() - 1, 1))}>‹</button><strong>{cursor.toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}</strong><button type="button" onClick={() => setCursor(new Date(cursor.getFullYear(), cursor.getMonth() + 1, 1))}>›</button></div><div className="source-calendar-week">{["Seg", "Ter", "Qua", "Qui", "Sex", "Sáb", "Dom"].map((item) => <span key={item}>{item}</span>)}</div><div className="source-calendar-days">{cells.map((day, index) => day ? <button type="button" key={day} className={String(value).slice(0, 10) === `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}` ? "selected" : ""} onClick={() => setDate(day)}>{day}</button> : <i key={`blank-${index}`} />)}</div></div>}</div>;
}
function MonthPicker({ value, onChange }) {
  const initial = String(value || new Date().toISOString()).slice(0, 10); const [open, setOpen] = useState(false); const [year, setYear] = useState(new Date(`${initial}T12:00:00`).getFullYear()); const pickerRef = useRef(null);
  useEffect(() => setYear(new Date(`${String(value || initial).slice(0, 10)}T12:00:00`).getFullYear()), [value]);
  useEffect(() => { if (!open) return undefined; const close = (event) => { if (!pickerRef.current?.contains(event.target)) setOpen(false); }; document.addEventListener("pointerdown", close); return () => document.removeEventListener("pointerdown", close); }, [open]);
  const selectedMonth = Number(String(value).slice(5, 7)) - 1; const months = Array.from({ length: 12 }, (_, month) => new Date(year, month, 1).toLocaleDateString("pt-BR", { month: "long" }));
  return <div className="source-picker" ref={pickerRef}><button type="button" className="source-picker-trigger" onClick={() => setOpen(!open)} aria-expanded={open}>{new Date(`${initial}T12:00:00`).toLocaleDateString("pt-BR", { month: "long", year: "numeric" })}<span>▾</span></button>{open && <div className="source-calendar source-month-calendar"><div className="source-calendar-head"><button type="button" onClick={() => setYear(year - 1)}>‹</button><strong>{year}</strong><button type="button" onClick={() => setYear(year + 1)}>›</button></div><div className="source-calendar-months">{months.map((month, index) => <button type="button" key={month} className={year === new Date(`${initial}T12:00:00`).getFullYear() && index === selectedMonth ? "selected" : ""} onClick={() => { onChange(`${year}-${String(index + 1).padStart(2, "0")}-01`); setOpen(false); }}>{month}</button>)}</div></div>}</div>;
}
function BrazilianDateInput(props) { return <CalendarPicker {...props} />; }
function BrazilianDateTimeInput(props) { return <CalendarPicker {...props} withTime />; }

function UserMenu({ userId }) {
  const [open, setOpen] = useState(false); const [changingPassword, setChangingPassword] = useState(false); const current = USERS.find((item) => item.id === userId) || USERS[0];
  useEffect(() => { if (!open) return undefined; const closeOnOutsideClick = (event) => { if (!event.target.closest(".user-menu")) setOpen(false); }; const closeOnEscape = (event) => { if (event.key === "Escape") setOpen(false); }; document.addEventListener("pointerdown", closeOnOutsideClick); document.addEventListener("keydown", closeOnEscape); return () => { document.removeEventListener("pointerdown", closeOnOutsideClick); document.removeEventListener("keydown", closeOnEscape); }; }, [open]);
  return <div className="user-menu"><button className="user-menu-trigger" type="button" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen(!open)}><span>{current.name}{current.role === "ADMIN" ? " — Admin" : ""}</span><b aria-hidden="true">⌄</b></button>{open && <div className="user-menu-list" role="menu"><div className="source-user-summary"><span>{current.name}</span><small>{current.role === "ADMIN" ? "Administrador" : "Operacional"}</small></div>{changingPassword ? <OwnPasswordForm onClose={() => setChangingPassword(false)} /> : <><button type="button" role="menuitem" onClick={() => setChangingPassword(true)}><span>Alterar senha</span><small>Definir nova senha</small></button><button type="button" role="menuitem" onClick={() => supabase.auth.signOut()}><span>Sair</span><small>Encerrar sessão</small></button></>}</div>}</div>;
}

function OwnPasswordForm({ onClose }) {
  const [password, setPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  const submit = async (event) => { event.preventDefault(); setError(""); if (password.length < 8) return setError("A senha deve ter ao menos 8 caracteres."); if (password !== confirmation) return setError("As senhas não coincidem."); setSaving(true); const { error: updateError } = await supabase.auth.updateUser({ password }); setSaving(false); if (updateError) return setError(updateError.message || "Não foi possível alterar a senha."); onClose(); };
  return <form className="source-user-password-form" onSubmit={submit}><h4>Alterar senha</h4><Field label="Nova senha" required type="password" value={password} onChange={setPassword} /><Field label="Confirmar senha" required type="password" value={confirmation} onChange={setConfirmation} /><div className="row-actions"><button type="button" className="ghost small-action" onClick={onClose}>Voltar</button><button className="primary" type="submit" disabled={saving}>{saving ? "Salvando..." : "Salvar"}</button></div>{error && <p className="source-access-error" role="alert">{error}</p>}</form>;
}

